package io.github.alien2003.teamsbridge.proto

import org.json.JSONObject
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertThrows
import org.junit.Assert.assertTrue
import org.junit.Test
import java.util.Base64
import javax.crypto.Cipher
import javax.crypto.spec.IvParameterSpec
import javax.crypto.spec.SecretKeySpec

/** Decryption (and, for parity, encryption) of every message vector generated by the Go side. */
class VectorsTest {
    private val key = TestVectors.key

    @Test
    fun vectorsCoverEveryMessageType() {
        val types = TestVectors.messages.map { it.getString("t") }.toSet()
        assertEquals(setOf(Message.MSG, Message.ALERT, Message.HB, Message.PAIR), types)
        assertTrue(TestVectors.messages.any { it.getBoolean("truncated") })
        assertTrue(TestVectors.messages.any { it.getInt("padded_len") == Proto.LARGE_PAD })
    }

    @Test
    fun runtimeHasChaCha20Poly1305() {
        // On a JDK the Android name is unknown and the fallback is used; on Android the first one.
        assertTrue(Aead.transformation in setOf("ChaCha20/Poly1305/NoPadding", "ChaCha20-Poly1305"))
    }

    @Test
    fun everyMessageDecryptsToTheExactJson() {
        for (v in TestVectors.messages) {
            val name = v.getString("name")
            val c = v.getString("sealed_b64")
            val sealed = Base64.getDecoder().decode(c)
            assertEquals(name, v.getString("nonce_hex"), sealed.copyOf(Proto.NONCE_SIZE).toHex())
            assertEquals(name, v.getString("ciphertext_hex"), sealed.copyOfRange(Proto.NONCE_SIZE, sealed.size).toHex())

            val padded = Aead.open(key, sealed)
            assertEquals(name, v.getInt("padded_len"), padded.size)
            assertEquals(name, v.getString("padded_hex"), padded.toHex())

            val json = Envelope.openJson(key, c)
            assertArrayEquals(name, v.getString("json").toByteArray(Charsets.UTF_8), json)
            assertEquals(name, Padding.sizeFor(json.size), padded.size)
        }
    }

    @Test
    fun everyMessageParsesToTheVectorFields() {
        for (v in TestVectors.messages) {
            val name = v.getString("name")
            val m = Envelope.open(key, v.getString("sealed_b64"))
            // Independent reading of the same JSON text.
            val o = JSONObject(v.getString("json"))
            assertEquals(name, 1, m.v)
            assertEquals(name, v.getString("t"), m.t)
            assertEquals(name, o.getString("id"), m.id)
            assertEquals(name, o.getLong("ts"), m.ts)
            for ((field, value) in listOf("title" to m.title, "body" to m.body, "url" to m.url, "tag" to m.tag, "kind" to m.kind)) {
                assertEquals("$name.$field", o.optString(field, ""), value)
            }
        }
    }

    @Test
    fun knownVectorContents() {
        val byName = TestVectors.messages.associateBy { it.getString("name") }
        val msg = Envelope.open(key, byName.getValue("msg").getString("sealed_b64"))
        val expected = Message(
            v = 1,
            t = "msg",
            id = "6f9619ff-8b86-4d01-b42d-00c04fc964ff",
            ts = 1767225600,
            title = "Alice",
            body = "hi",
            url = "https://teams.microsoft.com/v2/?tbdChat=19%3Aabc%40thread.v2",
            tag = "19:abc@thread.v2",
        )
        assertEquals(expected, msg)
        fun kind(name: String) = Envelope.open(key, byName.getValue(name).getString("sealed_b64")).kind
        assertEquals(Message.KIND_SESSION_EXPIRED, kind("alert_session_expired"))
        assertEquals(Message.KIND_BROWSER_DEAD, kind("alert_browser_dead"))
        assertEquals(Message.KIND_DAEMON_STOPPING, kind("alert_daemon_stopping"))
        val unicode = Envelope.open(key, byName.getValue("msg_unicode").getString("sealed_b64"))
        assertTrue(unicode.title.startsWith("Борис <b>&</b>"))
        val long = byName.getValue("msg_long")
        val lm = Envelope.open(key, long.getString("sealed_b64"))
        assertTrue(lm.body.endsWith("…"))
        assertTrue(lm.body.codePointCount(0, lm.body.length) < long.getInt("input_body_runes"))
        assertTrue(Envelope.openJson(key, long.getString("sealed_b64")).size <= Proto.MAX_PAYLOAD)
    }

    @Test
    fun encryptionMatchesGo() {
        for (v in TestVectors.messages) {
            val name = v.getString("name")
            val nonce = hex(v.getString("nonce_hex"))
            val json = v.getString("json").toByteArray(Charsets.UTF_8)
            assertEquals(name, v.getString("padded_hex"), Padding.pad(json).toHex())
            assertEquals(name, v.getString("sealed_b64"), Envelope.seal(key, nonce, json))
        }
    }

    @Test
    fun fcmRequestsOfTheVectors() {
        val topic = Secret.of(TestVectors.secret).topic()
        for (v in TestVectors.messages) {
            val msg = v.getJSONObject("fcm_request").getJSONObject("message")
            assertEquals(topic, msg.getString("topic"))
            assertEquals("high", msg.getJSONObject("android").getString("priority"))
            val ttl = if (v.getString("t") == Message.HB) "21600s" else "3600s"
            assertEquals(ttl, msg.getJSONObject("android").getString("ttl"))
            val data = msg.getJSONObject("data")
            assertEquals(setOf("c"), data.keys().asSequence().toSet())
            val c = data.getString("c")
            assertEquals(v.getString("sealed_b64"), c)
            // PROTOCOL.md §6: c is 1404 or 2768 characters, far below FCM's 4096-byte limit.
            assertEquals(if (v.getInt("padded_len") == Proto.SMALL_PAD) 1404 else 2768, c.length)
        }
    }

    @Test
    fun everyInvalidSealedVectorIsRejectedForItsReason() {
        // name → a word of the ProtoException message, so each vector exercises its own rule.
        val expected = mapOf(
            "nonzero_padding" to "non-zero padding",
            "length_overflow" to "declared length",
            "small_in_large" to "small size",
            "not_json" to "JSON",
            "wrong_version" to "version",
            "unknown_type" to "unknown message type",
            "odd_size" to "sealed length",
            "tampered" to "authentication",
        )
        val vectors = TestVectors.invalidSealed
        assertEquals(expected.keys, vectors.map { it.getString("name") }.toSet())
        for (v in vectors) {
            val name = v.getString("name")
            val e = assertThrows(name, ProtoException::class.java) { Envelope.open(key, v.getString("sealed_b64")) }
            assertTrue("$name: ${e.message}", e.message!!.contains(expected.getValue(name)))
        }
    }

    @Test
    fun wrongKeyOrMangledInputIsRejected() {
        val c = TestVectors.messages.first().getString("sealed_b64")
        val wrong = key.copyOf().also { it[0] = (it[0].toInt() xor 1).toByte() }
        assertThrows(ProtoException::class.java) { Envelope.open(wrong, c) }
        assertThrows(ProtoException::class.java) { Envelope.open(key, "not base64!") }
        assertThrows(ProtoException::class.java) { Envelope.open(key, "") }
        assertThrows(ProtoException::class.java) { Envelope.open(key, c.substring(0, c.length - 4)) }
        // Flipping any single byte of nonce, ciphertext or tag fails authentication.
        val sealed = Base64.getDecoder().decode(c)
        for (i in listOf(0, 11, 12, 500, sealed.size - 17, sealed.size - 1)) {
            val bad = sealed.copyOf().also { it[i] = (it[i].toInt() xor 0x80).toByte() }
            assertThrows("byte $i", ProtoException::class.java) { Aead.open(key, bad) }
        }
    }

    @Test
    fun otherAadIsRejected() {
        // Same key, nonce and plaintext, sealed with the AAD of a hypothetical v2: must not open.
        val v = TestVectors.messages.first()
        val nonce = hex(v.getString("nonce_hex"))
        val c = Cipher.getInstance(Aead.transformation)
        c.init(Cipher.ENCRYPT_MODE, SecretKeySpec(key, "ChaCha20"), IvParameterSpec(nonce))
        c.updateAAD("tbd:v2".toByteArray())
        val sealed = nonce + c.doFinal(hex(v.getString("padded_hex")))
        assertThrows(ProtoException::class.java) { Aead.open(key, sealed) }
        assertNotEquals(v.getString("sealed_b64"), Base64.getEncoder().encodeToString(sealed))
    }
}
